// Node "Préparer les changements" (Code, run once for all items).
// Input: the Notion query of "Devis à suivre" rows whose "À envoyer à Furious" is
// checked, i.e. "Statut" was changed in Notion and differs from "Statut Furious".
// Output: one item per row. action "envoyer" when the new status has a Furious
// pipe (with the query that reads the devis); action "annuler" (status put back,
// message in "Retour Furious") otherwise. Bodies and queries are built here
// because they contain "}}", which ends an n8n expression.

const PIPES = {
  'brief': 5,
  'en cours': 0,
  'envoyée(s) attente réponse': 4,
  'envoyée(s) en attente de réponse': 4,
};

const plain = (prop) => (prop?.rich_text ?? prop?.title ?? []).map((part) => part?.plain_text ?? '').join('').trim();
const key = (name) => String(name ?? '').normalize('NFC').trim().toLowerCase();

// Properties to write on the row: "Statut Furious" confirmed, "Statut" put back
// to what Furious has, "Retour Furious" set to the message (only when it changes).
function notionProperties(row, { confirm = false, revert = false, message = '' }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  const text = String(message).slice(0, 1900);
  if (text !== row.retour_actuel) {
    properties['Retour Furious'] = { rich_text: text ? [{ type: 'text', text: { content: text } }] : [] };
  }
  return properties;
}

const out = [];
for (const item of $input.all()) {
  for (const page of item.json.results ?? []) {
    const props = page.properties ?? {};
    const row = {
      page_id: page.id,
      devis_id: plain(props['ID Devis']),
      titre: plain(props['Name']),
      statut: props['Statut']?.status?.name ?? '',
      statut_furious: props['Statut Furious']?.select?.name ?? '',
      retour_actuel: plain(props['Retour Furious']),
    };
    row.pipe_cible = PIPES[key(row.statut)] ?? null;
    let refusal = '';
    if (!/^\d+$/.test(row.devis_id)) {
      refusal = "Pas d'ID Devis sur cette ligne : statut non envoyé à Furious.";
    } else if (row.pipe_cible === null) {
      refusal = `« ${row.statut} » ne se choisit pas dans Notion : un devis perdu ou signé se marque dans Furious. `
        + 'Dans Notion : brief, en cours, envoyée(s) attente réponse, ou gagné en attendant la signature.';
    }
    if (!refusal) {
      const query = `{ Proposal(limit: 1, offset: 0, filter: {id: {eq: "${row.devis_id}"}})`
        + '{ id, statut, pipe, cf_bu, cf_typologie_de_devis, cf_typologie_myrium } }';
      out.push({ json: { ...row, action: 'envoyer', furious_query: query } });
      continue;
    }
    const properties = notionProperties(row, { revert: true, message: refusal });
    if (Object.keys(properties).length) out.push({ json: { ...row, action: 'annuler', notion_body: { properties } } });
  }
}
return out;

// Node "Devis à envoyer" (Code, run once for all items).
// Runs after "Furious : connexion" (one login per run). Returns the rows of the
// true branch of "À envoyer à Furious ?" with action "envoyer" when the login
// worked. When Furious refuses the login (wrong or expired password in the n8n
// credential), the rows get action "connexion_refusee": their status is put back
// and the run stops in error, so n8n does not retry the login every two minutes
// (repeated failures could lock the Furious account, which the Myrium sync uses
// too). When Furious does not answer, the run fails and the rows stay pending.

const MESSAGE = 'n8n ne peut plus se connecter à Furious (identifiants à mettre à jour dans n8n) : '
  + 'statut remis comme avant. Le changer dans Furious en attendant.';

function notionProperties(row, { confirm = false, revert = false, message = '' }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  const text = String(message).slice(0, 1900);
  if (text !== row.retour_actuel) {
    properties['Retour Furious'] = { rich_text: text ? [{ type: 'text', text: { content: text } }] : [] };
  }
  return properties;
}

const login = $('Furious : connexion').first().json ?? {};
const rows = $('À envoyer à Furious ?').all(0).map((item) => item.json);
const status = login.statusCode;

if (login.error || !status || status >= 500 || status === 408 || status === 429) {
  const why = status ?? login.error?.message ?? 'pas de réponse';
  throw new Error(`Furious ne répond pas à la connexion (${why}) : nouvel essai au prochain passage.`);
}
if (login.body?.success === true && login.body?.token) {
  return rows.map((row) => ({ json: { ...row, action: 'envoyer' } }));
}
return rows.map((row) => ({
  json: { ...row, action: 'connexion_refusee', notion_body: { properties: notionProperties(row, { revert: true, message: MESSAGE }) } },
}));

// Node "Décider" (Code, run once for all items).
// Input: the answers of "Furious : lire le devis", paired with the rows of the true
// branch of "Connexion acceptée ?". For each devis, compares what Furious has now
// with the status chosen in Notion:
//   maj        Furious must change: the update body is prepared (item goes on)
//   a_jour     Furious already has that status: "Statut Furious" is confirmed
//   annuler    the change cannot be made: status put back, message written
//   reessayer  Furious did not answer: row left pending, message written once
// Every update re-sends the three custom fields of the devis (Furious refuses an
// update without them). "Typologie Myrium" is read back truncated ("PA " for
// "PA <= 15 000€"), so it is mapped to its full label.

const WAITING = { '5': 'Brief', '0': 'En cours', '4': 'Envoyée(s) attente réponse' };
const TYPOLOGIE_MYRIUM = [['PA', 'PA <= 15 000€'], ['CH', 'CH >= 15 000€']];
const RETRY = 'Furious ne répond pas : nouvel essai automatique dans quelques minutes.';

const decode = (text) => String(text ?? '')
  .replace(/&#0*39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const first = (value) => (Array.isArray(value) ? value[0] : value);
const pairedIndex = (item, i) => {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return typeof paired?.item === 'number' ? paired.item : i;
};
const transient = (res) => Boolean(res?.error) || !res?.statusCode || res.statusCode >= 500
  || [401, 403, 408, 429].includes(res.statusCode) || typeof res.body !== 'object' || res.body === null;

function notionProperties(row, { confirm = false, revert = false, message = '' }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  const text = String(message).slice(0, 1900);
  if (text !== row.retour_actuel) {
    properties['Retour Furious'] = { rich_text: text ? [{ type: 'text', text: { content: text } }] : [] };
  }
  return properties;
}

const rows = $('Connexion acceptée ?').all(0);
const out = [];
const settle = (row, action, options) => {
  const properties = notionProperties(row, options);
  if (Object.keys(properties).length) out.push({ json: { ...row, action, notion_body: { properties } } });
};

$input.all().forEach((item, i) => {
  const row = { ...rows[pairedIndex(item, i)].json };
  const res = item.json ?? {};
  const found = res.body?.data?.Proposal;
  if (transient(res) || !Array.isArray(found)) return settle(row, 'reessayer', { message: RETRY });

  const proposal = found.find((p) => String(p?.id ?? '') === row.devis_id);
  if (!proposal) {
    return settle(row, 'annuler', { revert: true, message: `Devis ${row.devis_id} introuvable dans Furious : statut remis comme avant.` });
  }
  const pipe = String(proposal.pipe ?? '');
  if (!(pipe in WAITING)) {
    return settle(row, 'annuler', {
      revert: true,
      message: `Ce devis est déjà « ${decode(proposal.statut) || pipe} » dans Furious : statut remis comme avant. `
        + 'La synchro du matin mettra la ligne à jour.',
    });
  }
  if (Number(pipe) === row.pipe_cible) return settle(row, 'a_jour', { confirm: true });

  const customFields = [];
  const bu = decode(first(proposal.cf_bu)).trim();
  if (bu) customFields.push({ name: 'bu', value: bu });
  const typologies = (Array.isArray(proposal.cf_typologie_de_devis)
    ? proposal.cf_typologie_de_devis
    : String(proposal.cf_typologie_de_devis ?? '').split(/\|#\||,/))
    .map((value) => decode(value).trim()).filter(Boolean);
  if (typologies.length) customFields.push({ name: 'typologie_de_devis', value: typologies });
  const myriumRead = decode(first(proposal.cf_typologie_myrium)).trim();
  if (myriumRead) {
    const myrium = TYPOLOGIE_MYRIUM.find(([prefix]) => myriumRead.toUpperCase().startsWith(prefix));
    if (!myrium) {
      return settle(row, 'annuler', {
        revert: true,
        message: `Typologie Myrium « ${myriumRead} » inconnue de l'automatisation : statut remis comme avant, le changer dans Furious.`,
      });
    }
    customFields.push({ name: 'typologie_myrium', value: myrium[1] });
  }
  out.push({
    json: {
      ...row,
      action: 'maj',
      statut_furious_actuel: WAITING[pipe],
      furious_body: { action: 'update', data: { id: Number(row.devis_id), pipe: row.pipe_cible, custom_fields: customFields } },
    },
  });
});
return out;

// Node "Lire la réponse de Furious" (Code, run once for all items).
// Input: the answers of "Furious : changer le statut", paired with the rows of the
// true branch of "Mettre à jour Furious ?". Furious answers HTTP 200 in both cases:
// {"success": true, "id": ...} when the status changed, {"success": false,
// "message": [...]} when it refused (e.g. "BU est requis", "Pipe invalide").
//   ok         "Statut Furious" confirmed, message cleared
//   annuler    refused: status put back, Furious's reason in "Retour Furious"
//   reessayer  no usable answer: row left pending (the next run reads the devis
//              again, so an update that did go through is only confirmed)

const RETRY = 'Furious ne répond pas : nouvel essai automatique dans quelques minutes.';

const decode = (text) => String(text ?? '')
  .replace(/&#0*39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const pairedIndex = (item, i) => {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return typeof paired?.item === 'number' ? paired.item : i;
};
const transient = (res) => Boolean(res?.error) || !res?.statusCode || res.statusCode >= 500
  || [401, 403, 408, 429].includes(res.statusCode) || typeof res.body !== 'object' || res.body === null;

function reason(body) {
  const raw = body?.message ?? body?.error ?? '';
  const parts = (Array.isArray(raw) ? raw : [raw])
    .map((part) => decode(typeof part === 'string' ? part : (part?.message ?? JSON.stringify(part))).trim())
    .filter(Boolean);
  return parts.join(' ; ').slice(0, 600) || 'réponse inattendue';
}

function notionProperties(row, { confirm = false, revert = false, message = '' }) {
  const properties = {};
  if (confirm) properties['Statut Furious'] = { select: { name: row.statut } };
  if (revert && row.statut_furious) properties['Statut'] = { status: { name: row.statut_furious } };
  const text = String(message).slice(0, 1900);
  if (text !== row.retour_actuel) {
    properties['Retour Furious'] = { rich_text: text ? [{ type: 'text', text: { content: text } }] : [] };
  }
  return properties;
}

const rows = $('Mettre à jour Furious ?').all(0);
const out = [];
const settle = (row, action, options) => {
  const properties = notionProperties(row, options);
  if (Object.keys(properties).length) out.push({ json: { ...row, action, notion_body: { properties } } });
};

$input.all().forEach((item, i) => {
  const { furious_body, ...row } = rows[pairedIndex(item, i)].json;
  const res = item.json ?? {};
  if (transient(res)) return settle(row, 'reessayer', { message: RETRY });
  if (res.body.success === true) return settle(row, 'ok', { confirm: true });
  return settle(row, 'annuler', {
    revert: true,
    message: `Furious a refusé le changement : ${reason(res.body)}. Statut remis comme avant.`,
  });
});
return out;
